          padding: '0.75rem 1.5rem',
          backgroundColor: '#3b82f6',
          color: 'white',
          textDecoration: 'none',
          borderRadius: '0.5rem',
          fontWeight: '500',
          transition: 'background-color 0.2s'
        }}
      >
        Go back home
      </Link>
    </main>
  );
